CREATE TABLE IF NOT EXISTS public.driver_guarantors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, driver_id uuid NOT NULL REFERENCES public.drivers(id) ON DELETE CASCADE, guarantor_id uuid NOT NULL REFERENCES public.guarantors(id) ON DELETE CASCADE, relationship text, liability_amount numeric, status text NOT NULL DEFAULT 'PENDING', verified_at timestamptz, verified_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(driver_id, guarantor_id));